@if ($errors->any())<div class="alert alert-danger"><ul class="mb-0 ps-3">@foreach ($errors->all() as $error)<li>{{ $error }}</li>@endforeach</ul></div>@endif
<div class="row g-3"><div class="col-md-8"><label class="form-label">Judul Dokumen</label><input name="title" class="form-control" value="{{ old('title', $isoDocument->title ?? '') }}" required></div><div class="col-md-4"><label class="form-label">Kategori</label><select name="category" class="form-select" required><option value="">-- Pilih Kategori --</option>@foreach(['Inventaris IT','Prosedur Kerja','Formulir ISO','Kebijakan','Laporan','Lainnya'] as $category)<option value="{{ $category }}" {{ old('category', $isoDocument->category ?? '') === $category ? 'selected' : '' }}>{{ $category }}</option>@endforeach</select></div><div class="col-md-4"><label class="form-label">Tanggal Dokumen</label><input type="date" name="document_date" class="form-control" value="{{ old('document_date', optional($isoDocument->document_date ?? null)->format('Y-m-d')) }}"></div><div class="col-md-4"><label class="form-label">Revisi</label><input name="revision" class="form-control" value="{{ old('revision', $isoDocument->revision ?? '') }}" placeholder="Contoh: 01"></div><div class="col-md-4"><label class="form-label">{{ isset($isoDocument) ? 'Ganti File Dokumen' : 'File Dokumen' }}</label><input id="document_file" type="file" name="document_file" class="form-control @error('document_file') is-invalid @enderror" accept=".pdf,.doc,.docx,.xls,.xlsx,.ppt,.pptx" {{ empty($isoDocument) ? 'required' : '' }}><small id="documentFileStatus" class="d-block text-muted">@if(isset($isoDocument))File saat ini: <strong>{{ $isoDocument->file_name }}</strong>. Pilih file baru untuk menggantikannya.@else PDF, Word, Excel, PowerPoint. Maks. 20 MB.@endif</small>@error('document_file')<div class="invalid-feedback">{{ $message }}</div>@enderror</div><div class="col-12"><label class="form-label">Deskripsi</label><textarea name="description" rows="3" class="form-control">{{ old('description', $isoDocument->description ?? '') }}</textarea></div><div class="col-12"><label class="form-label">Akses Pengguna</label><div class="border rounded p-3 bg-light"><div class="row g-2">@php($selectedUsers = old('permitted_user_ids', isset($isoDocument) ? $isoDocument->permittedUsers->pluck('id')->all() : []))@foreach($users as $user)<div class="col-md-4"><label class="form-check border rounded p-2 bg-white"><input class="form-check-input me-2" type="checkbox" name="permitted_user_ids[]" value="{{ $user->id }}" {{ in_array($user->id, $selectedUsers) ? 'checked' : '' }}><span><strong>{{ $user->name }}</strong><small class="d-block text-muted">{{ $user->department ?: 'Tanpa departemen' }} · {{ $user->roleLabel() }}</small></span></label></div>@endforeach</div></div><small class="text-muted">Pilih setidaknya satu pengguna yang boleh membuka dan mengunduh dokumen ini.</small></div></div>
<script>document.getElementById('document_file')?.addEventListener('change', event => { const file = event.target.files[0]; if (file) document.getElementById('documentFileStatus').textContent = 'File baru terpilih: ' + file.name; });</script>
